window.SQE_MINDMAPS["blp/business-structures"] = {
 "title": "Business structures and legal personality",
 "sub": "Five structures · separate personality · limited liability · piercing the veil · choosing",
 "branches": [
  {
   "h": "Sole trader",
   "pts": [
    "One person, **no registration** (just tell HMRC)",
    "**Not** a separate person: owner = business",
    "**Unlimited liability**: home and savings at risk",
    "Profits taxed as the owner's **income**"
   ]
  },
  {
   "h": "General partnership",
   "pts": [
    "Arises **automatically**: business in common with a view of profit (**PA 1890 s.1**)",
    "No paperwork needed; written agreement advisable",
    "**Unlimited liability**: any one partner can be made to pay the **whole debt** (s.9)",
    "Liable for partners' wrongs in the ordinary course of business (ss.10, 12)"
   ]
  },
  {
   "h": "LLP",
   "pts": [
    "Only by **registering at Companies House** (LLPA 2000)",
    "**Separate legal person**",
    "Members' liability **limited** to agreed contribution",
    "Taxed like a partnership; needs **2 designated members**",
    "Not the same as a **limited partnership (LP)**"
   ]
  },
  {
   "h": "Companies (Ltd and plc)",
   "pts": [
    "Created by **registration** under CA 2006",
    "Shareholders' liability = amount **unpaid on shares**",
    "**Ltd**: **no minimum share capital** (a single 1p share will do)",
    "**plc**: can offer shares to the public; needs **£50,000** allotted share capital and a **trading certificate**",
    "Company pays **corporation tax** on its profits"
   ]
  },
  {
   "h": "Separate legal personality",
   "pts": [
    "**Salomon** (1897): bootmaker's company is a separate person; its debts are not his",
    "**Macaura** (1925): timber belonged to the company, so his own insurance failed",
    "**Lee v Lee's Air Farming** (1961): director can also be the company's **employee**",
    "Each group company is separate (**Adams v Cape**)"
   ]
  },
  {
   "h": "Limited liability",
   "pts": [
    "A feature of the **members**, not the company",
    "The **company** is liable for all its own debts",
    "Lost in practice through **personal guarantees**, the director's **own tort**, or **statute** (e.g. wrongful trading)",
    "None of these is piercing the veil"
   ]
  },
  {
   "h": "Piercing the veil",
   "pts": [
    "**Very rare**: court treats company's rights or debts as the owner's",
    "**Prest v Petrodel** (2013): only if a company is used to **evade an existing legal obligation**",
    "**Gilford Motor v Horne**: sham company to dodge a restrictive covenant",
    "**Jones v Lipman**: house moved to a company to avoid a sale",
    "Not just because it seems **fair** (Adams v Cape)"
   ]
  },
  {
   "h": "Choosing a structure",
   "pts": [
    "Not registered? Then **sole trader or partnership**: unlimited liability",
    "High risk or big debts: **LLP or company**",
    "Professionals wanting flexibility + tax transparency: **LLP**",
    "Reinvesting profits or outside investors: **private company**"
   ]
  }
 ]
};
