SQE_CHECKS["legalsys/judicial-review-procedure"] = [
  {sec: "Nature of judicial review", after: 1, type: "mcq",
   q: "A claimant wins a judicial review of a council's decision to refuse her a licence. What is the usual result?",
   o: ["The court grants her the licence itself",
       "The decision is quashed and the council decides again lawfully, possibly reaching the same result",
       "The court awards damages in every case",
       "The council's officers are held in contempt"],
   a: 1, why: "JR is supervisory, not appellate: the court reviews legality, not merits."},
  {sec: "Amenability: is the decision open to judicial review?", after: 2, type: "match",
   prompt: "Match each decision to whether it is amenable to judicial review",
   pairs: [["A statutory licensing committee refuses a taxi licence","Amenable: statutory public power"],
           ["A self-regulating City panel with no statutory powers, performing a public regulatory function","Amenable: nature of the function (Datafin)"],
           ["A racing body, whose power over owners comes from contract, disqualifies a horse","Not amenable: power comes from contract"],
           ["An NHS trust dismisses a nurse under his employment contract","Not amenable: private law act of a public body"]]},
  {sec: "Standing (locus standi)", after: 2, type: "mcq",
   q: "A national campaign group with expertise challenges a minister's decision of real public importance that no individual is likely to challenge. It relies on ordinary JR grounds and also on Article 8 ECHR. What is the likely position on standing?",
   o: ["It has no standing at all, because it is not personally affected",
       "It has standing for both the ordinary grounds and the Article 8 claim",
       "It likely has a sufficient interest for ordinary JR, but cannot rely on Article 8 unless it is itself a victim under s.7 HRA",
       "It may rely on Article 8 but not on the ordinary grounds"],
   a: 2, why: "Pressure groups often have sufficient interest (s.31(3) SCA 1981; World Development Movement), but HRA claims need a victim."},
  {sec: "Time limits", after: 3, type: "gap",
   text: "A judicial review of a planning decision must be brought within [[six weeks]] of the grounds arising, and a letter before claim does not stop time running.",
   why: "CPR 54.5(5); only the court can extend time, not the parties."},
  {sec: "Procedure step by step", after: 1, type: "order",
   prompt: "Put these judicial review steps in order",
   items: ["Letter before claim under the pre-action protocol","File claim form N461 with grounds","Serve the defendant and interested parties within 7 days","Defendant files acknowledgment of service within 21 days","Court decides permission, usually on the papers","Substantive hearing"]},
  {sec: "Procedure step by step", after: 2, type: "reveal",
   prompt: "What must the court do at the permission stage if it is highly likely the outcome for the claimant would not have been substantially different without the conduct complained of?",
   answer: "It must refuse permission (s.31(3C)-(3F) SCA 1981), unless it certifies an exceptional public interest in allowing the claim."}
];

SQE_CHECKS["legalsys/judicial-review-grounds"] = [
  {sec: "The grounds at a glance", after: 1, type: "reveal",
   prompt: "Before you read on: what are Lord Diplock's three heads of judicial review in GCHQ, and what is the usual fourth ground?",
   answer: "1) Illegality. 2) Irrationality. 3) Procedural impropriety. The fourth is legitimate expectation."},
  {sec: "Illegality", after: 5, type: "gap",
   text: "Councillors who ban stag hunting on council land because they find it morally repugnant, without asking whether the ban benefits the area as the statute requires, have taken account of an [[irrelevant]] consideration.",
   why: "Fewings: the decision must be based on considerations the statute requires, not ones it excludes."},
  {sec: "Illegality", after: 13, type: "match",
   prompt: "Match the facts to the illegality sub-ground",
   pairs: [["A council refuses every licence from out-of-borough traders and will not hear any exceptions","Fettering discretion"],
           ["A minister refuses a referral because the result might embarrass the government","Improper purpose"],
           ["A local board's disciplinary power is exercised by the port manager","Unlawful delegation"],
           ["A body misreads the statutory test it must apply","Error of law"]]},
  {sec: "Irrationality", after: 1, type: "gap",
   text: "A decision is irrational only if it is so unreasonable that [[no reasonable authority]] could ever have come to it, so disagreeing with the merits is not enough.",
   why: "Wednesbury; GCHQ. Proportionality applies in HRA cases, not as a general ground."},
  {sec: "Procedural impropriety", after: 7, type: "mcq",
   q: "The chair of a planning committee is a non-executive director of the company applying for permission. He votes to grant it and there is no evidence he was actually biased. What test decides whether the decision can be quashed?",
   o: ["Whether the claimant can prove actual bias on the balance of probabilities",
       "Whether the observer would conclude the decision was in fact biased",
       "Whether a fair-minded and informed observer would conclude there was a real possibility of bias",
       "Whether the chair's vote changed the outcome"],
   a: 2, why: "Porter v Magill sets the apparent bias test; actual bias need not be proved."},
  {sec: "Procedural impropriety", after: 9, type: "order",
   prompt: "Put the four Gunning principles for fair consultation in the order a consultation runs",
   items: ["Consult while the proposals are at a formative stage","Give enough reasons to allow an intelligent response","Allow adequate time for responses","Conscientiously take the responses into account"]},
  {sec: "Legitimate expectation", after: 2, type: "mcq",
   q: "A health authority promised a small group of disabled residents that a care home would be their home for life. It now wants to close the home to save money, with no overriding public interest. What is the strongest argument for the residents?",
   o: ["A procedural legitimate expectation of consultation only",
       "Breach of contract, since the promise was a binding agreement",
       "Apparent bias, because the authority benefits from the saving",
       "A substantive legitimate expectation, which it would be so unfair to frustrate as to be an abuse of power"],
   a: 3, why: "Coughlan: a specific promise to a small group of a particular benefit, with no overriding public interest to justify breaking it."},
  {sec: "Remedies", after: 2, type: "match",
   prompt: "Match each remedy to what it does",
   pairs: [["Quashing order","Sets aside the unlawful decision"],
           ["Prohibiting order","Stops a body doing something unlawful it is about to do"],
           ["Mandatory order","Requires a body to perform a public duty"],
           ["Declaration","States the legal position without being coercive"]]},
  {sec: "Ouster clauses", after: 3, type: "mcq",
   q: "An Act says a commission's determinations \"shall not be called in question in any court\". The commission misreads its rules and rejects a claim. Can the High Court review the decision?",
   o: ["Yes, because a decision based on an error of law is only a purported determination, which the ouster does not protect",
       "No, because the words of the Act are clear and Parliament is sovereign",
       "Only if the claimant applies within six weeks",
       "No, unless the commission acted in bad faith"],
   a: 0, why: "Anisminic: total ouster clauses are read very narrowly; an error of law makes the decision a nullity."}
];

