SQE_CHECKS["trusts/certainties"] = [
  {sec: "The big idea in one paragraph", after: 3, type: "match",
   prompt: "Match each failed certainty to its result",
   pairs: [["No intention to create a trust","The recipient keeps the property as an outright gift"],
           ["The trust property cannot be identified","No trust at all: the settlor keeps the property"],
           ["Property certain but beneficial shares uncertain","Resulting trust for the settlor"],
           ["Beneficiaries cannot be identified by the right test","Resulting trust for the settlor or estate"]]},
  {sec: "Certainty of intention", after: 2, type: "gap",
   text: "Words of hope or wish such as \"in full confidence\" are [[precatory]] and usually create no trust, so the recipient takes an outright gift unless the document read as a whole shows an obligation.",
   why: "Re Adams and the Kensington Vestry; contrast Comiskey v Bowring-Hanbury."},
  {sec: "Certainty of subject matter", after: 3, type: "mcq",
   q: "Which of these declarations has certain subject matter?",
   o: ["\"The bulk of my savings\" on trust for my nephew",
       "\"50 of my 950 ordinary shares in X Ltd\" on trust for my employee",
       "\"20 cases of the wine in my warehouse stock\", never separated out, on trust for a customer",
       "\"Shares in my five best performing companies\" on trust for my niece, with no criteria"],
   a: 1, why: "Identical intangible shares need not be segregated (Hunter v Moss); bulk, unseparated tangible goods and unmeasured standards are uncertain."},
  {sec: "Certainty of subject matter", after: 6, type: "gap",
   text: "A direction that a beneficiary receive a \"[[reasonable income]]\" from the testator's properties is certain, because it gives an objective yardstick the court can apply.",
   why: "Re Golay's Will Trusts."},
  {sec: "Certainty of objects", after: 5, type: "reveal",
   prompt: "A settlor leaves £500,000 to trustees to distribute \"among my good friends as my trustees select\". Classify the trust and say why it is likely to fail.",
   answer: "It is a discretionary trust, so the is or is not test applies (McPhail v Doulton). It is likely to fail for conceptual uncertainty: \"good friends\" cannot be defined clearly enough to say of any given person whether they are in the class. Contrast an individual gift to each friend (Re Barlow)."},
  {sec: "Certainty of objects", after: 7, type: "match",
   prompt: "Match each type of disposition to its test for objects",
   pairs: [["Fixed trust \"for my employees equally\"","Complete list test"],
           ["Discretionary trust for relatives","Is or is not test, plus administrative workability"],
           ["Mere power of appointment","Is or is not test; width alone does not defeat it"],
           ["Option for any friends to buy paintings","Each claimant can be tested individually"]]},
  {sec: "Fixed and discretionary trusts in more detail", after: 3, type: "mcq",
   q: "Trustees hold a fund \"for such of the inhabitants of a county of 2.5 million people as they select\". The class is conceptually clear. Is the trust valid?",
   o: ["Yes, because the class is conceptually certain",
       "Yes, because evidential uncertainty does not matter",
       "No, because the complete list test cannot be satisfied",
       "No, because a discretionary trust for so wide a class is administratively unworkable"],
   a: 3, why: "R v District Auditor ex p West Yorkshire: an unworkably wide discretionary trust is void, even if conceptually clear."}
];

